from pathlib import Path
import subprocess,csv,io,json,datetime,collections,statistics
OUT=Path(__file__).parent
MYSQL=['/usr/local/mysql/bin/mysql','--login-path=meijendel_root','--host=127.0.0.1','--protocol=TCP','--batch','Meijendel']
def fetch(name,sql):
 p=subprocess.run(MYSQL,input='START TRANSACTION READ ONLY;\n'+sql+'\nCOMMIT;',capture_output=True,text=True,check=True)
 rows=list(csv.DictReader(io.StringIO(p.stdout),delimiter='\t'))
 (OUT/(name+'.json')).write_text(json.dumps({'executed_at':datetime.datetime.now().isoformat(),'query':sql,'rows':rows},ensure_ascii=False,indent=2))
 print(name,len(rows),flush=True);return rows
if __name__=='__main__':
 fetch('visits',"SELECT a.*,p.kavel_nummer,MONTH(a.bezoekdatum) maand FROM v_sovon_avimap_daz_analyse a JOIN v_meijendel_analyseplot_actueel p ON p.plot_id=a.plot_id WHERE a.wetenschappelijke_naam='Oryctolagus cuniculus';")
 fetch('points',"SELECT w.batch_id,w.bron_waarneming_id,w.bron_bezoek_id,w.plot_id,p.kavel_nummer,w.jaar,w.maand,w.waarnemingsdatum,w.aantal,w.in_plot,w.lopend_jaar,ST_Intersects(w.geom,p.geom) binnen_geom FROM sovon_avimap_waarneming w JOIN sovon_avimap_import_batch i ON i.batch_id=w.batch_id AND i.actueel=1 JOIN sovon_avimap_taxon t ON t.batch_id=w.batch_id AND t.soortgroep_code=w.soortgroep_code AND t.soortnr=w.soortnr JOIN taxa_bronkoppeling tb ON tb.koppeling_id=t.taxon_bronkoppeling_id JOIN v_meijendel_analyseplot_actueel p ON p.plot_id=w.plot_id WHERE tb.taxon_id=38949;")
 fetch('bird_coverage',"SELECT p.kavel_nummer,b.jaar,COUNT(*) bmp_bezoeken FROM dagbezoeken_bmp b JOIN v_meijendel_analyseplot_actueel p ON p.plot_id=b.plot_id WHERE b.jaar BETWEEN 2009 AND 2026 GROUP BY p.kavel_nummer,b.jaar;")
 fetch('historical_positive',"SELECT m.*,v.plot_id,p.kavel_nummer,v.jaar,v.bezoek_datum bezoekdatum FROM daz_bmp_bezoek_taxon m JOIN taxa_bronkoppeling t ON t.koppeling_id=m.taxon_bronkoppeling_id JOIN dagbezoeken_bmp v ON v.bezoek_id=m.bezoek_id JOIN v_meijendel_analyseplot_actueel p ON p.plot_id=v.plot_id WHERE t.taxon_id=38949 AND m.reconstructieversie='sovon-bmp-jaarbestanden-v1';")
 fetch('ndff',"SELECT a.*,p.kavel_nummer,w.telonderwerp,w.periode_start FROM Meijendel_ndff_secure.v_ndff_analyse_record a JOIN v_meijendel_analyseplot_actueel p ON p.plot_id=CAST(a.plot_id AS UNSIGNED) JOIN ndff_open_waarneming w ON w.waarneming_id=a.open_waarneming_id WHERE a.wetenschappelijke_naam='Oryctolagus cuniculus' AND a.record_selectiestatus='voorlopig_bruikbaar';")

def calculate():
 load=lambda name:json.loads((OUT/(name+'.json')).read_text())['rows']
 visits=load('visits');points=load('points');bird=load('bird_coverage');ndff=load('ndff');hist=load('historical_positive')
 assert len({(x['batch_id'],x['bron_bezoek_id']) for x in visits})==len(visits)
 assert len({(x['batch_id'],x['bron_waarneming_id']) for x in points})==len(points)
 assert all(x['in_plot']==x['binnen_geom'] for x in points)
 sums=collections.defaultdict(int)
 for x in points:
  if x['in_plot']=='1':sums[(x['batch_id'],x['bron_bezoek_id'])]+=int(x['aantal'])
 for x in visits:
  x['n']=sums[(x['batch_id'],x['bron_bezoek_id'])];x['year']=int(x['jaar']);x['month']=int(x['maand']);x['duration']=float(x['bezoekduur_min']) if x['bezoekduur_min']!='NULL' else None
 valid=[x for x in visits if x['record_selectiestatus']=='voorlopig_bruikbaar' and 2009<=x['year']<=2025]
 targets={'M15','M16','M17a'}
 def metric(rows):
  v=len(rows);s=sum(x['n'] for x in rows);p=sum(x['n']>0 for x in rows);mins=sum(x['duration'] or 0 for x in rows)
  return dict(visits=v,positive=p,total=s,per_visit=s/v if v else None,positive_pct=p/v*100 if v else None,plots=len({x['plot_id'] for x in rows}),years=len({x['year'] for x in rows}),hours=mins/60,per_hour=s/(mins/60) if mins else None)
 periods=[('voor',2009,2014),('aanleg',2015,2015),('eerste_vijf_na',2016,2020),('recent',2021,2025),('na',2016,2025),('laatste_twee',2024,2025),('voor_zonder_2014',2009,2013)]
 groups={'M15':{'M15'},'M16':{'M16'},'M17a':{'M17a'},'drie_kavels':targets,'overige_kavels':{x['kavel_nummer'] for x in visits}-targets}
 result={'periods':{},'annual':{},'coverage':[]}
 for label,ks in groups.items():
  result['periods'][label]={p:metric([x for x in valid if x['kavel_nummer'] in ks and a<=x['year']<=b]) for p,a,b in periods}
  result['annual'][label]=[{'year':y,**metric([x for x in valid if x['kavel_nummer'] in ks and x['year']==y])} for y in range(2009,2026)]
 for x in bird:
  if x['kavel_nummer'] in targets|{'M7','M45'}:
   rs=[v for v in visits if v['kavel_nummer']==x['kavel_nummer'] and v['year']==int(x['jaar'])]
   result['coverage'].append({**x,'daz_visits':len(rs),'comparable':sum(v['record_selectiestatus']=='voorlopig_bruikbaar' for v in rs)})
 allks=groups['overige_kavels']
 cohort=[]
 for k in sorted(allks):
  pre=[x for x in valid if x['kavel_nummer']==k and 2009<=x['year']<=2014]
  post=[x for x in valid if x['kavel_nummer']==k and 2021<=x['year']<=2025]
  if len(pre)>=15 and len(post)>=15 and len({x['year'] for x in pre})>=3 and len({x['year'] for x in post})>=3:cohort.append(k)
 result['matched_reference_plots']=cohort
 for key,ks in [('matched_reference',set(cohort)),('M15_M17a',{'M15','M17a'}),('rest_without_M42',allks-{'M42'})]:
  result['periods'][key]={p:metric([x for x in valid if x['kavel_nummer'] in ks and a<=x['year']<=b]) for p,a,b in periods}
  result['annual'][key]=[{'year':y,**metric([x for x in valid if x['kavel_nummer'] in ks and x['year']==y])} for y in range(2009,2026)]
 result['equal_plot']={}
 for key,ks in [('matched_reference',cohort),('M15_M17a',['M15','M17a']),('drie_kavels',['M15','M16','M17a'])]:
  result['equal_plot'][key]={}
  for period,a,b in periods:
   stats=[metric([x for x in valid if x['kavel_nummer']==k and a<=x['year']<=b]) for k in ks]
   stats=[x for x in stats if x['visits']]
   result['equal_plot'][key][period]={'plots':len(stats),'mean_per_visit':statistics.mean(x['per_visit'] for x in stats) if stats else None,'mean_positive_pct':statistics.mean(x['positive_pct'] for x in stats) if stats else None}
 result['march_june']={key:{p:metric([x for x in valid if x['kavel_nummer'] in ks and a<=x['year']<=b and 3<=x['month']<=6]) for p,a,b in periods} for key,ks in groups.items()}
 result['ndff_positive_live']={}
 for k in ['M15','M16','M17a','M7','M45']:
  rs=[x for x in ndff if x['kavel_nummer']==k]
  result['ndff_positive_live'][k]={'all_subjects':len(rs),'live_by_year':dict(sorted(collections.Counter(int(x['jaar']) for x in rs if x['telonderwerp']=='levend exemplaar').items())),'quality':list({(x['gegevensgeschiktheid'],x['kwaliteitsmelding']) for x in rs})}
 result['releases']={k:{p:metric([x for x in valid if x['kavel_nummer']==k and a<=x['year']<=b]) for p,a,b in [('2009_2014',2009,2014),('2015_2020',2015,2020),('2021_2022',2021,2022),('2023',2023,2023),('2024_2025',2024,2025)]} for k in ['M7','M45']}
 result['historic_2005_2008']=[x for x in hist if int(x['jaar'])<2009 and x['kavel_nummer'] in targets|{'M7','M45'}]
 result['partial_2026']={k:metric([x for x in visits if x['kavel_nummer'] in ks and x['year']==2026]) for k,ks in {**groups,'M7':{'M7'},'M45':{'M45'}}.items()}
 result['quality']={'visits':len(valid),'positive_points':sum(x['in_plot']=='1' and x['lopend_jaar']=='0' for x in points),'last_point':max(x['waarnemingsdatum'] for x in points),'excluded_visits':dict(collections.Counter(x['record_selectiestatus'] for x in visits if x['record_selectiestatus']!='voorlopig_bruikbaar')),'ndff_records':len(ndff),'historical_records':len(hist)}
 (OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
 print(json.dumps({k:v for k,v in result.items() if k not in ['annual','coverage','historic_2005_2008','march_june','equal_plot']},ensure_ascii=False,indent=2))
 return result
